// SPDX-License-Identifier: CC0-1.0

// Threshold weighting scores for various account characteristics.
const characteristicScores = {
  // Other accounts use the same IP address.
  associatedAccounts: 4,
  // Account has bio.
  bio: 1,
  /*
    IP address has changed since registration. This may indicate the account is being used by a different entity than
    the registrant, or the use of a VPN/proxy to bypass IP/locational restrictions.
  */
  ipChanged: 1,
  // Location has changed countries (possibly indicating use of VPN/proxy to circumvent IP/locational restrictions).
  migrated: 10,
  // Location specified in profile doesn't match IP address geolocation.
  profileLocationMismatch: 10,
  // IP address used by other suspended account.
  suspendedAssociation: 15,
  // Suspicious content in profile bio.
  suspiciousBio: 5,
  // Suspicious content in email.
  suspiciousEmail: 4,
  // Suspicious content in post.
  suspiciousPost: 3,
  // Suspicious content in profile website link.
  suspiciousWebsite: 6,
  // Profile has website link.
  website: 2,
};

const thresholdData = {
  /*
    User will be classified as "reviewable" if account stats do not surpass at least one of these thresholds.
    Thresholds are defined as a range. The effective threshold is weighted according to the account's scoring, as
    defined above.
  */

  /*
    Spammer accounts are often created some days before being used. However, it is likely that they will be used
    before too much time has passed.
    Unit: seconds.
  */
  accountAge: {
    description: "account age",
    range: {
      low: 8 * 24 * 60 * 60,
      high: 40 * 24 * 60 * 60,
    },
  },
  daysVisited: {
    description: "days visited",
    range: {
      low: 2,
      high: 6,
    },
  },
  // Includes topic original posts and replies.
  postCount: {
    description: "post count",
    range: {
      low: 1,
      high: 5,
    },
  },
  postsRead: {
    description: "posts read",
    range: {
      low: 4,
      high: 60,
    },
  },
  // Unit: seconds.
  timeReading: {
    description: "time spent reading",
    range: {
      low: 3 * 60,
      high: 15 * 60,
    },
  },
  topicsEntered: {
    description: "topics entered",
    range: {
      low: 2,
      high: 10,
    },
  },
  /*
    Note: A maximum trust level for general workflow run is configured in the configuration of the "Post edited"
    trigger, and in the "Low trust level?" filter node.
  */
  trustLevel: {
    description: "trust level",
    range: {
      low: 0,
      high: 1,
    },
  },
};

const associatedAccountData = $("Associated accounts").first().json;
const emailAddress = $("User email address").first().json.normalized_email;
const postData = $("Get post data").first().json;
const profileLocation = $("Profile location").item.json.profile_location;
const userData = $("User data").first().json;

const userLocations = {};
if ($("Profile location").item.json.profile_location != null) {
  userLocations.profile = $("Profile location").item.json.profile_location;
}

const userCharacteristics = {
  associatedAccounts: associatedAccountData.matching_account_count > 0,
  bio: !!userData.user.bio_raw,
  ipChanged: userData.user.ip_address !== userData.user.registration_ip_address,
  migrated:
    !!userData.user.last_location?.country &&
    !!userData.user.registration_location?.country &&
    userData.user.last_location.country !==
      userData.user.registration_location.country,
  // HHF: the original compared profile location with IP geolocation using
  // Discourse AI's classify node. Discourse AI is not enabled here.
  profileLocationMismatch: false,
  suspendedAssociation:
    associatedAccountData.matching_suspended_account_count > 0,
  suspiciousBio:
    !!userData.user.bio_raw && suspiciousContent(userData.user.bio_raw),
  suspiciousEmail: !!emailAddress && spamKeywords(emailAddress),
  suspiciousPost: !!postData.post?.raw && suspiciousContent(postData.post.raw),
  suspiciousWebsite:
    !!userData.user.website && spamKeywords(userData.user.website.toLowerCase()),
  website: !!userData.user.website,
};

const thresholdStats = {
  accountAge: (Date.now() - Date.parse(userData.user.created_at)) / 1000, // Seconds.
  daysVisited: userData.user.stats.days_visited,
  // `user.post_count` is actually only the reply count, so `user.topic_count` must be added in order to get the total
  //  post count.
  postCount: userData.user.stats.topic_count + userData.user.stats.post_count,
  postsRead: userData.user.stats.posts_read_count,
  timeReading: userData.user.stats.time_read, // Seconds.
  topicsEntered: userData.user.stats.topics_entered,
  trustLevel: userData.user.trust_level,
};

const userStats = {
  associatedAccountCount: associatedAccountData.matching_account_count,
  locations: userLocations,
  monitorGroup: monitorGroup(userData),
  staff: userData.user.staff,
};

if (reviewable()) {
  return [
    {
      flag: true,
      flag_type: userStats.monitorGroup ? "review_hide" : "review",
      reason: reason(),
    },
  ];
}

console.log(reason());

// Do not flag.
return [
  {
    flag: false,
    flag_type: "review",
    reason: "",
  },
];

// evaluateProfileLocationMatch evaluates the profile location vs. IP geolocation comparison data.
function evaluateProfileLocationMatch(
  lastLocationComparison,
  registrationLocationComparison,
) {
  const confidenceThreshold = 0.7;

  if (Object.keys(lastLocationComparison).includes("classification")) {
    if (
      lastLocationComparison.classification.match.choice === "false" &&
      lastLocationComparison.classification.match.confidence >=
        confidenceThreshold
    ) {
      return false;
    }
  }

  if (Object.keys(registrationLocationComparison).includes("classification")) {
    if (
      registrationLocationComparison.classification.match.choice === "false" &&
      registrationLocationComparison.classification.match.confidence >=
        confidenceThreshold
    ) {
      return false;
    }
  }

  return true;
}

// formatDuration formats a duration value into a human friendly format.
function formatDuration(totalSeconds) {
  const hours = Math.floor(totalSeconds / 3600)
    .toString()
    .padStart(2, "0");
  const minutes = Math.floor((totalSeconds % 3600) / 60)
    .toString()
    .padStart(2, "0");
  const seconds = Math.round(totalSeconds % 60)
    .toString()
    .padStart(2, "0");

  return `${hours}:${minutes}:${seconds} (H:M:S)`;
}

// monitorGroup returns whether the account is in the `monitor` user group.
function monitorGroup(data) {
  for (const group of data.user.groups || []) {
    // The `monitor_group_id` Workflow Variable is the ID of the `monitor` user group.
    if (group.id == $vars.monitor_group_id) {
      return true;
    }
  }

  return false;
}

// reason returns the text of the message that will be displayed in the flag.
function reason() {
  let reason = `<br />
**Account Stats**

- **Account age:** ${formatDuration(thresholdStats.accountAge)}
- **Associated account count:** ${userStats.associatedAccountCount}
- **Days visited:** ${thresholdStats.daysVisited}
- **Time spent reading posts:** ${formatDuration(thresholdStats.timeReading)}
- **Post count:** ${thresholdStats.postCount}
- **Posts read:** ${thresholdStats.postsRead}
- **Topics entered:** ${thresholdStats.topicsEntered}
- **Trust level:** ${thresholdStats.trustLevel}
`;

  if (userStats.monitorGroup) {
    reason = reason.concat(
      `

❗ User is a member of the "monitor" user group.
`,
    );
  }

  if (userCharacteristics.migrated) {
    reason = reason.concat(
      `

❗ User's location has changed countries.
This might indicate use of a proxy/VPN to circumvent location-based restrictions.
`,
    );
  } else if (userCharacteristics.ipChanged) {
    reason = reason.concat(
      `

❗ User's IP address has changed.
This might indicate use of a proxy/VPN to circumvent IP-based restrictions.
`,
    );
  }

  if (userCharacteristics.profileLocationMismatch) {
    reason = reason.concat(
      `

❗ User's IP address does not match the location "${userStats.locations.profile}" they specified in their account profile.
`,
    );
  }

  if (userCharacteristics.suspendedAssociation) {
    reason = reason.concat(
      `

❗ User IP address has been used by other suspended accounts.
This might indicate bulk account use for spam deployment.
`,
    );
  }

  if (userCharacteristics.suspiciousEmail) {
    reason = reason.concat(
      `

❗ User email address contains keywords commonly seen in those of spammer accounts.
`,
    );
  }

  return reason;
}

// reviewable returns whether the user is classified as "reviewable".
function reviewable() {
  if (userStats.staff) {
    /*
      In order to manage the `monitor` user group, moderators must be members of the group. For this reason, it is
      necessary to explicitly exempt them from being classified as "reviewable".
    */
    console.log("Not reviewable: user is staff.");
    return false;
  }

  if (userStats.monitorGroup) {
    // User is in the `monitor` user group, and thus is always reviewable regardless of other stats.
    console.log("Reviewable: user is in monitor group.");
    return true;
  }

  // Check if data indicate the user should be assigned a "reviewable" classification.
  const weight = thresholdWeight();

  for (const [stat, value] of Object.entries(thresholdStats)) {
    const threshold = Math.round(
      (thresholdData[stat].range.high - thresholdData[stat].range.low) *
        weight +
        thresholdData[stat].range.low,
    );

    if (value > threshold) {
      console.log(
        `Not reviewable: ${thresholdData[stat].description} ${value} exceeds threshold ${threshold}.`,
      );
      return false;
    }
  }

  console.log("Reviewable: account does not pass any threshold");
  return true;
}

// spamKeywords returns whether the given string contains keywords associated with spammers.
function spamKeywords(content) {
  const keywords = [
    "777",
    "agency",
    "apk",
    "app",
    "astrolog",
    "backlink",
    "brand",
    "casino",
    "chems",
    "club",
    "coin",
    "consultan",
    "crm",
    "crypto",
    "design",
    "digital",
    "escort",
    "estate",
    "fashion",
    "fitness",
    "game",
    "gelatin",
    "gift",
    "girls",
    "gluco",
    "gummies",
    "gummy",
    "homes",
    "logistic",
    "manage",
    "manufactur",
    "market",
    "meds",
    "menu",
    "official",
    "pcb",
    "pharma",
    "properties",
