    "website",
  ];

  for (const keyword of keywords) {
    if (content.includes(keyword)) {
      return true;
    }
  }

  return false;
}

// suspiciousContent returns whether the given string contains content common to spammer posts.
function suspiciousContent(content) {
  const suspiciousTexts = ["pcbcool", "digital market", "online marketing"];
  const suspiciousPatterns = [
    /*
      Multiple em dashes are sometimes utilized as a graphical element by legitimate users. It is only the solitary
      em dash used as punctuation that is the indicator of AI-generated content.
    */
    /.+[^—]—[^—].+/,
    /\bSEO\b/,
  ];

  for (const suspiciousText of suspiciousTexts) {
    if (content.toLowerCase().includes(suspiciousText)) {
      return true;
    }
  }
  for (const suspiciousPattern of suspiciousPatterns) {
    if (content.match(suspiciousPattern) != null) {
      return true;
    }
  }

  return false;
}

// thresholdWeight returns the threshold weight based on the given score.
function thresholdWeight() {
  let score = 0;

  // Add characteristic-based scores.
  for (const [characteristic, present] of Object.entries(userCharacteristics)) {
    if (present) {
      score += characteristicScores[characteristic];
    }
  }

  // Calculate maximum score.
  let maxCharacteristicScore = 0;
  for (const characteristicScore of Object.values(characteristicScores)) {
    maxCharacteristicScore += characteristicScore;
  }

  // Calculate weight.
  return score / maxCharacteristicScore;
}

var triggerData = {};

// Populate from step that triggered this run.
if (Object.keys($("DEBUG: Manual trigger").first().json).length !== 0) {
  triggerData = $("DEBUG: Manual trigger").first().json;
} else if (Object.keys($("Post created").first().json).length !== 0) {
  triggerData = $("Post created").first().json;
} else if (Object.keys($("Post edited").first().json).length !== 0) {
  triggerData = $("Post edited").first().json;
} else {
  throw new Error("Unknown trigger.");
}

// Standardize context data across all triggers.
if (!("debug" in triggerData)) {
  triggerData.debug = false;
}

if (!("wait" in triggerData)) {
  // HHF: no AI spam scan runs here, so there is nothing to wait for.
  triggerData.wait = false;
}

return [triggerData];
